import difflib
import json
import re
import subprocess
import tarfile
import time
import traceback

from zipfile import ZipFile

from taf.rfrl.csv4all.resources.node.exceptions import SuspiciousPrintsFoundError, BlackboxVerificationFailed
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.exceptions import LogsCheckError, SnapshotCollectError
from taf.rfrl.csv4all.resources.utilities.test_global_constants import UUF4ALL_BLACKBOX_PRINTS, RFRL_SYSLOG_PRINTS
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, run_and_continue_on_failure, \
    verify_function_x_times


class NodeLogsVerifier:
    def __init__(self, node_alias, admin, ssh_manager, watchdog, watchdog_config, use_dcap, dcap, btslog, aashell,
                 syslog_check, syslog_ignored_prints, user_syslog_suspicious_prints, detailed_console_log,
                 airphone):
        self.reset_counter = None
        self.watchdog_config = watchdog_config
        self.watchdog = watchdog
        self.admin = admin
        self.node_alias = node_alias
        self.ssh_manager = ssh_manager
        self.use_dcap = use_dcap
        self.dcap = dcap
        self.btslog = btslog
        self.aashell = aashell
        self.reset_check = True
        self.syslog_check = syslog_check
        self.syslog_ignored_prints = self.parse_ignored_prints(syslog_ignored_prints)
        self.syslog_prints = self._parse_suspicious_prints(user_syslog_suspicious_prints)
        self.set_current_reset_counter()
        self.logs_fault_message = ""
        self.detailed_console_log = detailed_console_log
        self.airphone = airphone

    @method_decorator("node_alias")
    def stop_trace_and_download_logs(self, logs_dir: str):
        try:
            if self.use_dcap:
                current_logs_path = self.dcap.stop_trace_and_download_logs(logs_dir=f"{logs_dir}/"
                                                                                    f"LOGS_FROM_{self.node_alias}")
            else:
                current_logs_path: list = verify_function_x_times(3, 10, self.btslog.stop_btslog_and_download_logs,
                                                                  logs_dir=f"{logs_dir}/LOGS_FROM_{self.node_alias}")
            test_logger(current_logs_path, console=False)
            return current_logs_path
        except Exception as btslog_error:
            self.btslog.running = False
            test_logger(btslog_error, 'error')
            return None

    @method_decorator("node_alias")
    def stop_logs_and_verify(self, logs_dir: str, reset_incrementation: bool = False):
        verify_function_x_times(3, 30, self.get_blackbox, logs_dir, f"blackbox_after_test_{self.node_alias}.txt")
        self.check_logs_for_crashes(logs_dir, self.stop_trace_and_download_logs(logs_dir),
                                    should_be_incremented=reset_incrementation)

    @method_decorator("node_alias")
    def check_logs_for_crashes(self, blackbox_dir: str, syslog_paths: list, should_be_incremented: bool = True):
        test_logger(f"Checking logs for crashes on {self.node_alias}", "info")
        logs_results = {"Blackbox Verification": run_and_continue_on_failure(self.verify_blackbox, blackbox_dir)}
        if self.syslog_check:
            for syslog_path in (syslog_paths or []):
                smod = "Secondary" if "secondary" in syslog_path.split("/")[-2] else "Primary"
                logs_results[f"{smod} Syslog Verification"] = run_and_continue_on_failure(self.verify_syslog,
                                                                                          syslog_path)
            if not syslog_paths:
                test_logger("Checking syslog failed. Provided path to syslog is empty", "error")
        if self.reset_check:
            logs_results["Reset Incrementation"] = run_and_continue_on_failure(
                self.check_reset_counter_incrementation, should_be_incremented)
        if not all(logs_result in [True, "Disabled"] for logs_result in logs_results.values()):
            test_logger(f"Logs check failed \n{json.dumps(logs_results, indent=4)}", "INFO")
            failed_logs_results = ", ".join([f"{operation}: Failed" for operation, status in logs_results.items()
                                             if status not in [True, "Disabled"]])
            self.logs_fault_message = f"\n{failed_logs_results}\n{self.logs_fault_message}"
            failed_operations = [operation for operation in logs_results.keys() if not logs_results[operation]]
            raise LogsCheckError(f"Checking logs failed in: {', '.join(failed_operations)}")

    @method_decorator("node_alias")
    def get_reset_counter(self) -> int:
        ddal_response = self.ssh_manager.execute_command("ddal -s ddal_lifetime_data_get_reset_counter_1 0")
        test_logger(f"current reset counter for {self.node_alias}: {ddal_response}", "debug")
        return int(ddal_response.splitlines()[1].split("=")[1])

    def set_current_reset_counter(self):
        self.reset_counter = self.get_reset_counter()

    @method_decorator("node_alias")
    def gather_airphone_snapshot(self, logs_dir):
        try:
            self.airphone.collect_snapshot(f"{logs_dir}/LOGS_FROM_{self.node_alias}/airphone_logs")
            test_logger("Snapshot from Airphone gathered successfully")
        except Exception as e:
            test_logger(e, "DEBUG")
            raise

    @method_decorator("node_alias")
    def gather_snapshot(self, logs_dir: str, file_name: str = "snapshot", snapshot_directory: str = None):
        """
        :param logs_dir:
        :param file_name:
        :param snapshot_directory:
        :return:
        """
        attempt_try = 5
        snapshot_directory = f"{logs_dir}/LOGS_FROM_{self.node_alias}/" if not snapshot_directory else \
            snapshot_directory
        snapshot_path = f"{snapshot_directory}/{file_name}.zip"
        for attempt in range(attempt_try):
            try:
                self.admin.get_snapshot(target_file_name=snapshot_path, timeout=3600)
                test_logger("Snapshot gathered successfully")
                break
            except Exception as e:
                test_logger(e, "DEBUG")
                if "Request rejected as site reset is ongoing" in str(e) or "Version request failed" in str(e):
                    self.admin.setup_node_admin()
                if attempt == attempt_try - 1:
                    try:
                        test_logger(f"Snapshot from admin failed {attempt_try} times. "
                                    f"Gathering snapshot from aashell started.", log_level="ERROR")
                        self.gather_snapshot_from_smod(snapshot_path.rsplit("/", 1)[0])
                    except Exception as e:
                        test_logger(e, console=False)
                        raise SnapshotCollectError("Collecting snapshot Failed")
                time.sleep(60)
                continue

    @method_decorator("node_alias")
    def gather_snapshot_from_smod(self, target_dir: str):
        self.aashell.get_snapshot_from_aashell(target_dir=target_dir, alias=self.node_alias)

    @method_decorator("node_alias")
    def check_reset_counter_incrementation(self, should_be_incremented: bool = True):
        try:
            counter_incrementation = self.get_reset_counter() - self.reset_counter
        except Exception as e:
            test_logger(e, "error", console=False)
            test_logger(traceback.format_exc(), log_level="debug", console=False)
            raise
        if str(should_be_incremented).lower() == "true":
            if counter_incrementation != 1:
                test_logger(f"Counter Error, reset counter incremented by {counter_incrementation}", "ERROR")
                return False
        elif str(should_be_incremented).lower() == "false":
            if counter_incrementation != 0:
                test_logger(f"Counter Error, reset counter incremented by {counter_incrementation}", "ERROR")
                return False
        return True

    @method_decorator("node_alias")
    def verify_syslog(self, syslog_dir: str):
        test_logger(f"Syslog ignored prints: {self.syslog_ignored_prints}", "DEBUG")
        test_logger(f"Syslog disallowed prints: {self.syslog_prints}", "DEBUG")
        suspicious_prints = []
        if self.use_dcap:
            with ZipFile(syslog_dir, 'r') as zipped_logs:
                log_files = zipped_logs.namelist()
                for single_file in log_files:
                    if re.search(r".*bts/syslog/.*\.LOG", single_file):
                        with zipped_logs.open(single_file, "r") as syslog:
                            syslog_lines = [line.decode('utf-8') for line in syslog.readlines()]
                            suspicious_prints += [line for line in syslog_lines if re.findall(self.syslog_prints, line,
                                                                                              flags=re.MULTILINE)]
        else:
            with tarfile.open(syslog_dir, 'r') as tar_logs:
                for single_file in tar_logs.getmembers():
                    if re.search(r".*\.LOG", single_file.name):
                        try:
                            syslog_lines = [line.decode("utf-8") for line in
                                            tar_logs.extractfile(single_file.name).readlines()]
                        except UnicodeError:
                            syslog_lines = [line.decode("iso-8859-1") for line in
                                            tar_logs.extractfile(single_file.name).readlines()]
                        suspicious_prints += [line for line in syslog_lines if re.findall(self.syslog_prints, line,
                                                                                          flags=re.MULTILINE)]
        if self.syslog_ignored_prints and suspicious_prints:
            suspicious_prints = [suspicious_print for suspicious_print in suspicious_prints
                                 if not any(ignored_print in suspicious_print
                                            for ignored_print in self.syslog_ignored_prints)]
        if suspicious_prints:
            self.logs_fault_message += "\n".join(suspicious_prints)
            log_lvl = "ERROR" if self.detailed_console_log else "DEBUG"
            test_logger("\n".join(suspicious_prints), log_level=log_lvl)
            raise SuspiciousPrintsFoundError(
                f"Found suspicious prints in file {single_file if self.use_dcap else single_file.name}")
        return True

    @method_decorator("node_alias")
    def verify_blackbox(self, blackboxes_dir: str):
        # Check if there is no new unexpected print i.e. "spurious reset" in blackbox file after test.
        results = self.compare_blackboxes(f"{blackboxes_dir}/LOGS_FROM_{self.node_alias}")
        test_logger(results, console=False)
        try:
            crashes = str(subprocess.check_output(f"grep '{UUF4ALL_BLACKBOX_PRINTS}' {results}", shell=True,
                                                  universal_newlines=True))
            test_logger(crashes, console=False)
            if crashes:
                self.logs_fault_message = f"\nBlackbox verification failed: {crashes}\n{self.logs_fault_message}"
                test_logger(
                    f"Blackbox verification failed :\n Crash has been found : \n{crashes}",
                    "error")
                raise BlackboxVerificationFailed()
            return True
        except subprocess.CalledProcessError as e:
            if e.returncode == 1:
                return True
            elif e.returncode == 2:
                raise RuntimeError(f"Error occurred during executing {e.cmd}")
        except Exception as e:
            test_logger(e, "error", console=False)
            test_logger(traceback.format_exc(), log_level="debug", console=False)
            raise

    def compare_blackboxes(self, blackboxes_dir: str):
        # Compare two given blackbox files and return difference between them.
        base_blackbox = f"{blackboxes_dir}/blackbox_before_test_{self.node_alias}.txt"
        after_test_blackbox = f"{blackboxes_dir}/blackbox_after_test_{self.node_alias}.txt"
        compare_results = f"{blackboxes_dir}/compare_results_{self.node_alias}.txt"
        with open(base_blackbox) as base_file, open(after_test_blackbox) as new_file, open(compare_results,
                                                                                           "w") as results:
            results.writelines("Results of blackbox comparison: \n")
            for line in difflib.ndiff(base_file.readlines(), new_file.readlines()):
                if line.startswith("+"):
                    results.write(line)
        return results.name

    @method_decorator("node_alias")
    def get_blackbox(self, target_dir: str, file_name: str = "blackbox.txt"):
        try:
            blackbox_dir = "/ffs/run/config/lifedata/" if self.ssh_manager.file_exists("/ffs/run/config/lifedata")\
                else "/ffs/run/logs/lifetimedata/"
            self.ssh_manager.get_file_from_bts(f"{blackbox_dir}/blackbox",
                                               f"{target_dir}/LOGS_FROM_{self.node_alias}",
                                               file_name)
        except Exception as e:
            test_logger(e, "ERROR")
            raise

    @staticmethod
    def _parse_suspicious_prints(suspicious_prints) -> str:
        if not suspicious_prints:
            return RFRL_SYSLOG_PRINTS
        if isinstance(suspicious_prints, list):
            suspicious_prints = [sus_print.strip() for sus_print in suspicious_prints]
            suspicious_prints = "|".join(suspicious_prints)
        return "|".join([RFRL_SYSLOG_PRINTS, suspicious_prints])

    @staticmethod
    def parse_ignored_prints(syslog_ignored_prints) -> list:
        if not syslog_ignored_prints:
            return []
        if isinstance(syslog_ignored_prints, str):
            temp_list = syslog_ignored_prints.split("|")
            return [ignored_print.strip() for ignored_print in temp_list]
        return syslog_ignored_prints
